(()=>{
 const panel=document.createElement('details');panel.id='ribbon-panel';panel.className='advanced';panel.innerHTML='<summary>Curved ribbons</summary><p class="animation-intro">A ribbon connects this layer’s particles in birth order. Use a continuous stream with a narrow emission point for a smooth trail. Lifetime controls determine how long the stream remains visible.</p>';
 const label=document.createElement('label');label.textContent='Trail style';const mode=document.createElement('select');mode.id='ribbon-mode';mode.setAttribute('aria-label','Trail style');mode.add(new Option('Straight streaks','streak'));mode.add(new Option('Connected ribbon','ribbon'));label.append(mode);panel.append(label);mode.onchange=()=>{state.trailMode=mode.value;state.trail=true;sync();persist();};
 const inputs={};for(const [key,name,min,max,step]of [['ribbonWidth','Ribbon width (cm)',.1,100,.1],['ribbonTaper','Taper toward older particles',0,1,.05]]){const row=document.createElement('label');row.textContent=name;const input=document.createElement('input');input.id='ribbon-'+key;input.type='number';Object.assign(input,{min,max,step});input.setAttribute('aria-label',name);input.oninput=()=>{if(!input.checkValidity()||!Number.isFinite(input.valueAsNumber))return;state[key]=input.valueAsNumber;persist();};row.append(input);panel.append(row);inputs[key]=input;}
 const example=document.createElement('button');example.id='ribbon-example';example.textContent='Add flowing ribbon';example.onclick=()=>addParticleLayer({...EmberCatalog.presets.find(p=>p.id==='custom'),name:'Flowing ribbon',amount:70,spread:5,size:1,life:4,motion:'aimed',velocityPitch:45,speed:65,windY:35,gravity:-25,turbulence:0,trail:true,trailMode:'ribbon',ribbonWidth:10,ribbonTaper:1,endOpacity:0},'Flowing ribbon');panel.append(example);$('#animation-panel').before(panel);
 function refresh(){mode.value=state.trailMode||'streak';for(const [key,input]of Object.entries(inputs)){input.value=state[key]??(key==='ribbonWidth'?8:1);input.disabled=state.trailMode!=='ribbon';}}
 const previous=sync;sync=()=>{previous();refresh();};refresh();
})();
